106: export async function POST(context: APIContext): Promise<Response> {
107: 	const env = await serverEnvironment();
108: 	const store = getBoardStore(env);
109: 	const key = clientKey(context.request);
110: 
111: 	// Abuse protection: cooldown + hourly cap, per client address.
112: 	// Uses shared KV-based rate limiting so different Worker isolates
113: 	// are throttled consistently.
114: 	if (!rateLimit(`board:post:${key}`, BOARD_CONFIG.postCooldownSeconds * 1000, 1)) {
115: 		return json(
116: 			{
117: 				error: 'rate_limited',
118: 				retryAfter: retryAfterSeconds(`board:post:${key}`, BOARD_CONFIG.postCooldownSeconds * 1000),
119: 			},
120: 			429,
121: 		);
122: 	}
123: 	if (!rateLimit(`board:hour:${key}`, 3_600_000, 20)) {
124: 		return json({ error: 'rate_limited', retryAfter: 60 }, 429);
125: 	}
126: 
127: 	let payload: unknown;
128: 	try {
129: 		payload = await context.request.json();
130: 	} catch {
131: 		return json({ error: 'invalid_json' }, 400);
132: 	}
133: 
134: 	const body = (payload ?? {}) as { text?: unknown; image?: unknown; status?: unknown };
135: 
136: 	// Enforce 250-character limit server-side (reject, don't truncate)
137: 	const text = typeof body.text === 'string' ? body.text.replace(CONTROL_CHARS, '').trim() : '';
138: 
139: 	if (text.length === 0) {
140: 		return json({ error: 'empty_text' }, 422);
141: 	}
142: 
143: 	if (text.length > BOARD_CONFIG.maxTextLength) {
144: 		return json(
145: 			{
146: 				error: 'text_too_long',
147: 				maxLength: BOARD_CONFIG.maxTextLength,
148: 				actualLength: text.length,
149: 			},
150: 			400,
151: 		);
152: 	}
153: 
154: 	const image = sanitizeImage(body.image);
155: 
156: 	// Validate status if provided (for future moderation operations)
157: 	// Default to 'visible' for new public messages
158: 	const status: MessageStatus = body.status && isValidStatus(body.status) ? body.status : 'visible';
159: 
160: 	const message: BoardMessage = {
161: 		id: `${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 8)}`,
162: 		text,
163: 		...(image ? { image } : {}),
164: 		// Stable tint seed, derived once so every visitor sees the same hue.
165: 		hue: Math.floor(Math.random() * 360),
166: 		status,
167: 		createdAt: Date.now(),
168: 	};
169: 
170: 	try {
171: 		await store.add(message);
172: 		return json({ message, provider: store.kind }, 201);
173: 	} catch (error) {
174: 		console.error('[bnji] board add failed:', error);
175: 		return json({ error: 'storage_unavailable' }, 503);
176: 	}
177: }

