1: /**
2:  * BNJI.NET — message board storage providers.
3:  *
4:  * The API route (src/pages/api/board.ts) talks only to this module; the UI
5:  * talks only to the API. That is the whole boundary: swapping persistence
6:  * never touches a component.
7:  *
8:  * Providers
9:  * ---------
10:  *  memory — module-scope array. Lives as long as the Worker isolate does, so
11:  *           messages are shared by visitors served by the same isolate and
12:  *           survive between requests, but not across isolates/deployments.
13:  *           Zero configuration; this is the default and the honest demo grade.
14:  *  d1     — Cloudflare D1 database, true persistence. Auto-detected: if the
15:  *           Worker environment exposes a BOARD_D1 database binding, this
16:  *           provider is used automatically. Enable it with:
17:  *             npx wrangler d1 create board
18:  *           then add a binding named BOARD_D1 in wrangler.json
19:  *           (see docs/CONFIGURATION.md). No code changes needed.
20:  *  kv     — Cloudflare KV, true persistence. Auto-detected: if the Worker
21:  *           environment exposes a BOARD_KV namespace binding, this provider is
22:  *           used automatically. Enable it with:
23:  *             npx wrangler kv namespace create board
24:  *           then add a binding named BOARD_KV in wrangler.json
25:  *           (see docs/CONFIGURATION.md). No code changes needed.
26:  *  rest   — external JSON API (GET/POST {messages}) for teams that already
27:  *           run a backend. Configured via BOARD_REST_URL / BOARD_REST_TOKEN
28:  *           environment variables (secret; never in this file).
29:  *
30:  * Data model (deliberately tiny and serialisable):
31:  *   { id, text, image?, hue, status, createdAt }
32:  * `image` is stored ONLY as a validated data: URL of an allowed MIME type and
33:  * size (validated again server-side on write). `hue` is a stable 0-359 tint
34:  * seed so each bubble/star gets its own colour without storing one.
35:  * `status` is a moderation field: 'visible' | 'hidden' | 'reported' | 'deleted'.
36:  * Non-visible messages never reach the public fetch endpoint.
37:  */
38: import { BOARD_CONFIG } from '../config/board.config';
39: 
40: export type MessageStatus = 'visible' | 'hidden' | 'reported' | 'deleted';
41: 
42: export type BoardMessage = {
43: 	id: string;
44: 	text: string;
45: 	/** Validated data: URL, or undefined. Never an arbitrary remote URL. */
46: 	image?: string;
47: 	/** Stable tint seed 0-359. */
48: 	hue: number;
49: 	/** Moderation status. Hidden/deleted/reported never reach the public fetch. */
50: 	status: MessageStatus;
51: 	/** Epoch ms. */
52: 	createdAt: number;
53: };
54: 
55: export type ListMessagesOptions = {
56: 	/** Maximum number of messages to return. */
57: 	limit: number;
58: 	/** Cursor for pagination (opaque encoded cursor). */
59: 	cursor?: string;
60: };
61: 
62: export type ListMessagesResult = {
63: 	/** Messages, newest first, filtered to visible only. */
64: 	messages: BoardMessage[];
65: 	/** Opaque cursor for the next page, or undefined if no more. */
66: 	nextCursor?: string;
67: };
68: 
69: export interface BoardStore {
70: 	/** Newest first, visible-only. Supports cursor-based pagination. */
71: 	listMessages(opts: ListMessagesOptions): Promise<ListMessagesResult>;
72: 	/** Store a new message. */
73: 	add(message: BoardMessage): Promise<void>;
74: 	/** Update a message's status (for moderation operations). */
75: 	updateStatus(id: string, status: MessageStatus): Promise<boolean>;
76: 	readonly kind: 'memory' | 'd1' | 'kv' | 'rest';
77: }
78: 
79: /* --- memory provider ------------------------------------------------------ */
80: 
81: const memory: BoardMessage[] = [];
82: 
83: const memoryStore: BoardStore = {
84: 	kind: 'memory',
85: 	async listMessages({ limit, cursor }) {
86: 		let items = memory
87: 			.slice()
88: 			.filter((m) => m.status === 'visible')
89: 			.sort((a, b) => b.createdAt - a.createdAt);
90: 
91: 		if (cursor) {
92: 			const decoded = decodeCursor(cursor);
93: 			if (decoded) {
94: 				// Find the position of the cursor message and get items after it
95: 				const cursorIdx = items.findIndex((m) => m.createdAt <= decoded);
96: 				if (cursorIdx !== -1) {
97: 					items = items.slice(cursorIdx);
98: 				} else if (decoded < items[items.length - 1]?.createdAt) {
99: 					// Cursor is older than the last available message; return empty
100: 					items = [];
101: 				}
102: 			}
103: 		}
104: 
105: 		const messages = items.slice(0, limit);
106: 		const nextCursor =
107: 			messages.length === limit && messages.length > 0
108: 				? encodeCursor(messages[messages.length - 1].createdAt)
109: 				: undefined;
110: 
111: 		return { messages, nextCursor };
112: 	},
113: 	async add(message) {
114: 		memory.push(message);
115: 		// Hard cap so a long-lived isolate cannot grow without bound.
116: 		if (memory.length > 500) memory.splice(0, memory.length - 500);
117: 	},
118: 	async updateStatus(id, status) {
119: 		const idx = memory.findIndex((m) => m.id === id);
120: 		if (idx === -1) return false;
121: 		memory[idx].status = status;
122: 		return true;
123: 	},
124: };
