128: type D1Database = {
129: 	prepare(query: string): {
130: 		bind(...values: unknown[]): { all: () => Promise<unknown[]>; run: () => Promise<{ success: boolean }>; first: () => Promise<unknown | null>; };
131: 	};
132: };
