134: /** Encode a cursor (createdAt timestamp) into an opaque token. */
135: function encodeCursor(createdAt: number): string {
136: 	return Buffer.from(`c:${createdAt}`).toString('base64url');
137: }
138: 
139: /** Decode a cursor token back to a createdAt timestamp. */
140: function decodeCursor(cursor: string): number | null {
141: 	try {
142: 		const decoded = Buffer.from(cursor, 'base64url').toString('utf8');
143: 		const match = /^c:(-?\d+)$/.exec(decoded);
144: 		return match ? Number(match[1]) : null;
145: 	} catch {
146: 		return null;
147: 	}
148: }
