150: function createD1Store(d1: D1Database): BoardStore {
151: 	// Initialize schema on first use
152: 	let schemaInitialized = false;
153: 
154: 	async function ensureSchema(): Promise<void> {
155: 		if (schemaInitialized) return;
156: 		schemaInitialized = true;
157: 		const stmt = d1.prepare(`
158: 			CREATE TABLE IF NOT EXISTS board_messages (
159: 				id TEXT PRIMARY KEY,
160: 				text TEXT NOT NULL,
161: 				image TEXT,
162: 				hue INTEGER NOT NULL,
163: 				status TEXT NOT NULL DEFAULT 'visible',
164: 				created_at INTEGER NOT NULL
165: 			)
166: 		`);
167: 		try {
168: 			await stmt.run();
169: 		} catch (e) {
170: 			console.error('[bnji] board d1 schema init failed:', e);
171: 		}
172: 	}
173: 
174: 	return {
175: 		kind: 'd1',
176: 		async listMessages({ limit, cursor }) {
177: 			await ensureSchema();
178: 
179: 			const args: unknown[] = [];
180: 			let query = `
181: 				SELECT id, text, image, hue, status, created_at as createdAt
182: 				FROM board_messages
183: 				WHERE status = 'visible'
184: 			`;
185: 
186: 			if (cursor) {
187: 				const decoded = decodeCursor(cursor);
188: 				if (decoded !== null) {
189: 					query += ` AND created_at <= ?`;
190: 					args.push(decoded);
191: 				}
192: 			}
193: 
194: 			query += ` ORDER BY created_at DESC LIMIT ?`;
195: 			args.push(limit);
196: 
197: 			try {
198: 				const stmt = d1.prepare(query);
199: 				const stmtBound = args.length > 0 ? stmt.bind(...args) : stmt;
200: 				const rows = (await stmtBound.all()) as Array<{
201: 					id: string;
202: 					text: string;
203: 					image: string | null;
204: 					hue: number;
205: 					status: string;
206: 					createdAt: number;
207: 				}>;
208: 
209: 				const messages: BoardMessage[] = rows.map((row) => ({
210: 					id: row.id,
211: 					text: row.text,
212: 					image: row.image ?? undefined,
213: 					hue: row.hue,
214: 					status: row.status as MessageStatus,
215: 					createdAt: row.createdAt,
216: 				}));
217: 
218: 				const nextCursor =
219: 					messages.length === limit && messages.length > 0
220: 						? encodeCursor(messages[messages.length - 1].createdAt)
221: 						: undefined;
222: 
223: 				return { messages, nextCursor };
224: 			} catch (error) {
225: 				console.error('[bnji] board d1 list failed:', error);
226: 				return { messages: [], nextCursor: undefined };
227: 			}
228: 		},
229: 		async add(message) {
230: 			await ensureSchema();
231: 			try {
232: 				await d1
233: 					.prepare(`
234: 						INSERT INTO board_messages (id, text, image, hue, status, created_at)
235: 						VALUES (?, ?, ?, ?, ?, ?)
236: 					`)
237: 					.bind(
238: 						message.id,
239: 						message.text,
240: 						message.image ?? null,
241: 						message.hue,
242: 						message.status,
243: 						message.createdAt,
244: 					)
245: 					.run();
246: 			} catch (error) {
247: 				console.error('[bnji] board d1 add failed:', error);
248: 				throw error;
249: 			}
250: 		},
251: 		async updateStatus(id, status) {
252: 			await ensureSchema();
253: 			try {
254: 				const result = await d1
255: 					.prepare(`UPDATE board_messages SET status = ? WHERE id = ?`)
256: 					.bind(status, id)
257: 					.run();
258: 				return result.success;
259: 			} catch (error) {
260: 				console.error('[bnji] board d1 updateStatus failed:', error);
