269: type KvNamespace = {
270: 	get(key: string): Promise<string | null>;
271: 	put(key: string, value: string): Promise<void>;
272: 	list(options?: { cursor?: string; limit?: number }): Promise<{
273: 		keys: string[];
274: 		list_complete: boolean;
275: 		cursor: string;
276: 	}>;
