279: function createKvStore(kv: KvNamespace): BoardStore {
280: 	// For KV, we'll store messages individually and use list() for pagination
281: 	// The cursor will be the KV list cursor
282: 	async function loadVisibleMessages(limit: number, cursor?: string): Promise<{
283: 		messages: BoardMessage[];
284: 		nextCursor?: string;
285: 	}> {
286: 		// In KV we store all messages; we need to scan through them
287: 		// This is a simplified approach - a production implementation would use
288: 		// a sorted index. For now, we'll load all and filter client-side.
289: 		const results: BoardMessage[] = [];
290: 		let currentCursor: string | undefined = cursor;
291: 
292: 		while (results.length < limit) {
293: 			const listResult = await kv.list({ cursor: currentCursor, limit: 100 });
294: 			if (listResult.keys.length === 0) break;
295: 
296: 			for (const key of listResult.keys) {
297: 				if (key.startsWith('board:msg:')) {
298: 					const raw = await kv.get(key);
299: 					if (raw) {
300: 						const msg = JSON.parse(raw) as BoardMessage;
301: 						if (msg.status === 'visible') {
302: 							results.push(msg);
303: 						}
304: 					}
305: 				}
306: 			}
307: 
308: 			if (listResult.list_complete) {
309: 				break;
310: 			}
311: 			currentCursor = listResult.cursor;
312: 		}
313: 
314: 		// Sort newest first
315: 		results.sort((a, b) => b.createdAt - a.createdAt);
316: 		const messages = results.slice(0, limit);
317: 		const nextCursor = messages.length === limit && messages.length > 0
318: 			? encodeCursor(messages[messages.length - 1].createdAt)
319: 			: undefined;
320: 
321: 		return { messages, nextCursor };
322: 	}
323: 
324: 	return {
325: 		kind: 'kv',
326: 		async listMessages({ limit, cursor }) {
327: 			try {
328: 				return await loadVisibleMessages(limit, cursor);
329: 			} catch (error) {
330: 				console.error('[bnji] board kv list failed:', error);
331: 				return { messages: [], nextCursor: undefined };
332: 			}
333: 		},
334: 		async add(message) {
335: 			try {
336: 				await kv.put(`board:msg:${message.id}`, JSON.stringify(message));
337: 			} catch (error) {
338: 				console.error('[bnji] board kv add failed:', error);
339: 				throw error;
340: 			}
341: 		},
342: 		async updateStatus(id, status) {
343: 			try {
344: 				const raw = await kv.get(`board:msg:${id}`);
345: 				if (!raw) return false;
346: 				const msg = JSON.parse(raw) as BoardMessage;
347: 				msg.status = status;
348: 				await kv.put(`board:msg:${id}`, JSON.stringify(msg));
349: 				return true;
350: 			} catch (error) {
351: 				console.error('[bnji] board kv updateStatus failed:', error);
352: 				return false;
353: 			}
354: 		},
355: 	};
356: }
