2:  * BNJI.NET — shared rate limiter using KV with TTL.
3:  *
4:  * Uses Cloudflare KV to store rate-limit counters with a TTL, so two requests
5:  * hitting different Worker isolates are still throttled consistently. Each
6:  * (clientKey, window) pair writes to a KV key that expires after the window.
7:  *
8:  * The counter is a sliding window: each request checks the current count and
9:  * increments it. KV's atomic increment operation ensures safe concurrent access.
10:  *
11:  * No secrets, no credentials: keys are hashed client addresses only. The KV
12:  * namespace should be bound as RATE_LIMIT_KV in wrangler.json.
13:  *
14:  * Falls back to in-isolate memory limiting when KV is unavailable.
15:  */
16: 
17: type KvNamespace = {
18: 	get(key: string): Promise<string | null>;
19: 	put(key: string, value: string, options?: { expirationTtl?: number }): Promise<void>;
20: 	// For atomic increments (CF Workers support this on KV)
21: 	// @ts-expect-error - KV binding has more methods than our type declares
22: 	increment?(key: string, amount?: number, options?: { expirationTtl?: number }): Promise<number>;
23: 	delete(key: string): Promise<void>;
24: };
25: 
26: type Bucket = { stamps: number[] };
27: 
28: // In-isolate fallback
29: const memoryBuckets = new Map<string, Bucket>();
30: const MAX_KEYS = 2000;
31: 
32: /**
33:  * @param key      client identity (e.g. Astro.clientAddress)
34:  * @param windowMs sliding window size
35:  * @param maxHits  allowed hits inside the window
36:  * @returns true when the hit is allowed (and recorded)
37:  */
38: export function rateLimit(key: string, windowMs: number, maxHits: number): boolean {
39: 	// If KV is available, use shared rate limiting
40: 	const kv = getRateLimitKv();
41: 	if (kv) {
42: 		return rateLimitKv(kv, key, windowMs, maxHits);
43: 	}
44: 	// Fallback to in-isolate memory limiting
45: 	return rateLimitMemory(key, windowMs, maxHits);
