48: /**
49:  * Seconds until the rate limit window resets (for Retry-After header).
50:  */
51: export function retryAfterSeconds(key: string, windowMs: number): number {
52: 	const kv = getRateLimitKv();
53: 	if (kv) {
54: 		return retryAfterSecondsKv(kv, key, windowMs);
55: 	}
56: 	const bucket = memoryBuckets.get(key);
57: 	if (!bucket || bucket.stamps.length === 0) return 0;
58: 	const oldest = bucket.stamps[0];
59: 	return Math.max(1, Math.ceil((windowMs - (Date.now() - oldest)) / 1000));
60: }
