86: async function rateLimitKv(
87: 	kv: KvNamespace,
88: 	clientKey: string,
89: 	windowMs: number,
90: 	maxHits: number,
91: ): boolean {
92: 	const key = `rl:${clientKey}:${windowMs}`;
93: 	const windowSec = Math.ceil(windowMs / 1000);
94: 
95: 	try {
96: 		// Try atomic increment first (best case)
97: 		if (kv.increment) {
98: 			const newValue = await kv.increment(key, 1, { expirationTtl: windowSec });
99: 			if (newValue <= maxHits) return true;
100: 			// Over the limit
101: 			await kv.delete(key);
102: 			return false;
103: 		}
104: 	} catch {
105: 		// Fall back to get/put if increment isn't supported
106: 	}
107: 
108: 	try {
109: 		const raw = await kv.get(key);
110: 		const count = raw ? parseInt(raw, 10) : 0;
111: 		if (count >= maxHits) return false;
112: 
113: 		await kv.put(key, String(count + 1), { expirationTtl: windowSec });
114: 		return true;
115: 	} catch (e) {
116: 		console.error('[bnji] rate limit kv failed, falling back to memory:', e);
117: 		return rateLimitMemory(clientKey, windowMs, maxHits);
118: 	}
