121: async function retryAfterSecondsKv(
122: 	kv: KvNamespace,
123: 	clientKey: string,
124: 	windowMs: number,
125: ): number {
126: 	const key = `rl:${clientKey}:${windowMs}`;
127: 	const windowSec = Math.ceil(windowMs / 1000);
128: 	try {
129: 		const raw = await kv.get(key);
130: 		const count = raw ? parseInt(raw, 10) : 0;
131: 		// Estimate based on time elapsed in the window
132: 		return Math.max(1, windowSec);
133: 	} catch {
134: 		return Math.max(1, Math.ceil(windowMs / 1000));
135: 	}
136: }
137: 
138: // --- Memory-based fallback rate limiting ---
139: 
140: function rateLimitMemory(key: string, windowMs: number, maxHits: number): boolean {
141: 	const now = Date.now();
142: 	let bucket = memoryBuckets.get(key);
143: 	if (!bucket) {
144: 		if (memoryBuckets.size > MAX_KEYS) {
145: 			// Prune stale keys instead of unbounded growth.
146: 			for (const [k, b] of memoryBuckets) {
147: 				if (b.stamps.length === 0 || now - b.stamps[b.stamps.length - 1] > windowMs) {
148: 					memoryBuckets.delete(k);
149: 				}
150: 			}
151: 		}
152: 		bucket = { stamps: [] };
153: 		memoryBuckets.set(key, bucket);
154: 	}
155: 	bucket.stamps = bucket.stamps.filter((t) => now - t < windowMs);
156: 	if (bucket.stamps.length >= maxHits) return false;
157: 	bucket.stamps.push(now);
158: 	return true;
159: }

